import urllib.request
import urllib.error
import time
from typing import Optional

class RateLimitError(Exception):
    """Raised when rate limited (HTTP 429) after retries."""
    pass

class ServerError(Exception):
    """Raised when server error (HTTP 5xx) persists after retry."""
    pass

class ClientError(Exception):
    """Raised for client errors (HTTP 4xx, except 429)."""
    pass

class ConnectionError(Exception):
    """Raised for network errors after retry."""
    pass

class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def _make_request(self, path: str) -> str:
        url = f"{self.base_url}{path}"
        req = urllib.request.Request(url)

        # Set a user agent to avoid being blocked by some servers
        req.add_header('User-Agent', 'APIClient/1.0')

        try:
            with urllib.request.urlopen(req, timeout=self.timeout) as response:
                return response.read().decode('utf-8')
        except urllib.error.HTTPError as e:
            status_code = e.code
            if status_code == 429:
                return self._handle_rate_limit(url)
            elif 500 <= status_code < 600:
                return self._handle_server_error(url)
            else:
                raise ClientError(f"Client error: {status_code}") from e
        except urllib.error.URLError as e:
            return self._handle_network_error(url, e)

    def _handle_rate_limit(self, url: str) -> str:
        """Handle HTTP 429 with exponential backoff (0.5s, 1s, 2s)."""
        backoff_delays = [0.5, 1.0, 2.0]
        for i, delay in enumerate(backoff_delays):
            time.sleep(delay)
            try:
                with urllib.request.urlopen(url, timeout=self.timeout) as response:
                    return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    continue
                elif 500 <= e.code < 600:
                    raise ServerError(f"Server error after rate limit retry: {e.code}") from e
                else:
                    raise ClientError(f"Client error after rate limit retry: {e.code}") from e
            except urllib.error.URLError as e:
                raise ConnectionError(f"Network error after rate limit retry") from e

        raise RateLimitError("Rate limited after all retries")

    def _handle_server_error(self, url: str) -> str:
        """Handle HTTP 5xx with one retry after 1s."""
        time.sleep(1)
        try:
            with urllib.request.urlopen(url, timeout=self.timeout) as response:
                return response.read().decode('utf-8')
        except urllib.error.HTTPError as e:
            if 500 <= e.code < 600:
                raise ServerError(f"Server error persists: {e.code}") from e
            else:
                raise ClientError(f"Unexpected client error after server retry: {e.code}") from e
        except urllib.error.URLError as e:
            raise ConnectionError(f"Network error after server retry") from e

    def _handle_network_error(self, url: str, error: urllib.error.URLError) -> str:
        """Handle network errors with one retry after 1s."""
        time.sleep(1)
        try:
            with urllib.request.urlopen(url, timeout=self.timeout) as response:
                return response.read().decode('utf-8')
        except urllib.error.HTTPError as e:
            if e.code == 429:
                return self._handle_rate_limit(url)
            elif 500 <= e.code < 600:
                return self._handle_server_error(url)
            else:
                raise ClientError(f"Client error after network retry: {e.code}") from e
        except urllib.error.URLError as e:
            raise ConnectionError("Network error persists after retry") from e

    def get(self, path: str) -> str:
        """Make a GET request and return the response body as a string."""
        return self._make_request(path)
